'use strict';var USERS=[];var ROLES=[];var LOCATIONS=[];var AREAS=[];var deleteTarget={type:null,id:null};var ICON_PENCIL=Icons.pencil;var ICON_TRASH=Icons.trash;function loadUsers(){return api('GET','/api/users').then(function(data){USERS=data||[];renderAdminUsers()})}
function loadRoles(){return api('GET','/api/roles').then(function(data){ROLES=data||[];renderRoleOptions()})}
function loadLocations(){return api('GET','/api/locations').then(function(data){LOCATIONS=data||[];renderLocationOptions()}).catch(function(){})}
function loadAreas(){return api('GET','/api/areas').then(function(data){AREAS=data||[];renderAreaOptions()}).catch(function(){})}
function renderRoleOptions(selectedRole){var select=document.getElementById('fUserRole');if(!select)return;if(!ROLES.length){select.innerHTML='<option value="">Nenhum perfil encontrado</option>';return}
select.innerHTML=ROLES.map(function(r){var isSel=(selectedRole&&selectedRole===r.name)||(!selectedRole&&r.name==='Admin');return'<option value="'+esc(r.name)+'"'+(isSel?' selected':'')+'>'+esc(r.name)+'</option>'}).join('')}
function renderLocationOptions(selectedLocId){var select=document.getElementById('fUserLocation');if(!select)return;var selId=selectedLocId?Number(selectedLocId):null;var html='<option value="">Nenhuma / Sem restrição</option>';html+=LOCATIONS.map(function(loc){var isSel=selId===Number(loc.id);return'<option value="'+loc.id+'"'+(isSel?' selected':'')+'>'+esc(loc.name)+'</option>'}).join('');select.innerHTML=html}
function renderAreaOptions(selectedAreaId){var select=document.getElementById('fUserArea');if(!select)return;var selId=selectedAreaId?Number(selectedAreaId):null;var html='<option value="">Nenhuma / Sem restrição</option>';html+=AREAS.map(function(area){var isSel=selId===Number(area.id);return'<option value="'+area.id+'"'+(isSel?' selected':'')+'>'+esc(area.name)+'</option>'}).join('');select.innerHTML=html}
var userFilterQuery='';function clearUserSearch(){var input=document.getElementById('userSearchInput');var clearBtn=document.getElementById('userSearchClear');if(input)input.value='';if(clearBtn)clearBtn.hidden=!0;userFilterQuery='';PAGINATION.usr=1;renderAdminUsers()}
window.clearUserSearch=clearUserSearch;function renderAdminUsers(){var sortState=TableSort.getSort('userTable');var q=userFilterQuery.toLowerCase().trim();var users=USERS.filter(function(u){if(!q)return!0;var login=(u.login||u.username||'').toLowerCase();var name=(u.name||'').toLowerCase();var email=(u.email||'').toLowerCase();var role=(u.role||'').toLowerCase();var loc=(u.location_name||'').toLowerCase();var area=(u.area_name||'').toLowerCase();var status=(u.status||'').toLowerCase();return login.indexOf(q)!==-1||name.indexOf(q)!==-1||email.indexOf(q)!==-1||role.indexOf(q)!==-1||loc.indexOf(q)!==-1||area.indexOf(q)!==-1||status.indexOf(q)!==-1});if(sortState.col){users=TableSort.sortArray(users,sortState.col,sortState.dir,function(u,col){if(col==='username')return u.login;if(col==='name')return u.name;if(col==='role')return u.role;if(col==='location')return u.location_name||'';if(col==='area')return u.area_name||'';if(col==='status')return u.status;return u.login})}
var logins=users.map(function(u){return u.login});var pg=paginated('usr',logins);document.getElementById('adminUserBody').innerHTML=pg.total?pg.page.map(function(login){var u=USERS.find(function(x){return x.login===login});var roleLabel='<span class="kanban-label kanban-label-purple">'+esc(u.role)+'</span>';var statusCls=u.status==='ativo'?'status status-green':'status status-red';var statusLabel=u.status==='ativo'?'Ativo':'Inativo';var locBadge=u.location_name?'<span class="badge" style="background:rgba(26,187,156,0.1);color:#1abb9c;font-weight:600;padding:3px 8px;border-radius:6px;font-size:0.75rem;display:inline-flex;align-items:center;gap:4px;">'+Icons.get('location',{size:11})+esc(u.location_name)+'</span>':'<span style="opacity:0.4;font-size:0.8rem;">—</span>';var areaBadge=u.area_name?'<span class="badge" style="background:rgba(99,102,241,0.1);color:#6366f1;font-weight:600;padding:3px 8px;border-radius:6px;font-size:0.75rem;display:inline-flex;align-items:center;gap:4px;">'+Icons.get('area',{size:11})+esc(u.area_name)+'</span>':'<span style="opacity:0.4;font-size:0.8rem;">—</span>';var row='<tr data-id="'+esc(login)+'">';row+='<td class="cell-mono">'+esc(login)+'</td>';row+='<td class="cell-strong">'+esc(u.name)+'</td>';row+='<td>'+roleLabel+'</td>';row+='<td>'+locBadge+'</td>';row+='<td>'+areaBadge+'</td>';row+='<td><span class="'+statusCls+'">'+statusLabel+'</span></td>';row+='<td><div class="table-actions">'+'<button class="table-action-btn" title="Editar" aria-label="Editar '+esc(login)+'" onclick="abrirModalUsuario(\''+esc(login)+'\')">'+Icons.pencil+'</button>';if(login!=='admin'){row+='<button class="table-action-btn del" title="Excluir" aria-label="Excluir '+esc(login)+'" onclick="confirmDeleteUser(\''+esc(login)+'\')">'+Icons.trash+'</button>'}
row+='</div></td></tr>';return row}).join(''):'<tr><td colspan="7">'+'<div class="empty-state"><div class="empty-state-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="8"/><line x1="21" y1="21" x2="16.65" y2="16.65"/></svg></div>'+'<div class="empty-state-title">Nenhum usuário encontrado</div>'+'</div></td></tr>';renderPagination('userPagination',pg.total,pg.current,pg.pages,function(p){PAGINATION.usr=p;renderAdminUsers()})}
function abrirModalUsuario(login){var isEdit=!!login;var user=isEdit?USERS.find(function(u){return u.login===login||u.username===login}):null;var isAdminPrincipal=login==='admin';document.getElementById('modalUserTitulo').textContent=isEdit?'Editar Usuário':'Novo Usuário';document.getElementById('uId').value=login||'';document.getElementById('fUserLogin').value=login||'';document.getElementById('fUserLogin').disabled=isEdit;document.getElementById('fUserNome').value=isEdit?user.name:'';if(document.getElementById('fUserEmail')){document.getElementById('fUserEmail').value=(isEdit&&user.email)?user.email:''}
document.getElementById('fUserPass').value='';renderRoleOptions(isEdit?user.role:(ROLES[0]?ROLES[0].name:'Admin'));renderLocationOptions(isEdit?user.location_id:null);renderAreaOptions(isEdit?user.area_id:null);document.getElementById('fUserRole').disabled=isAdminPrincipal;document.getElementById('fUserStatus').value=isEdit?user.status:'ativo';document.getElementById('fUserStatus').disabled=isAdminPrincipal;openModal('modalUserBG');setTimeout(function(){if(isEdit){document.getElementById('fUserNome').focus()}else{document.getElementById('fUserLogin').focus()}},50)}
function fecharModalUsuario(){closeModal('modalUserBG')}
function salvarUsuario(){var isEdit=!!document.getElementById('uId').value;var login=document.getElementById('fUserLogin').value.trim().toLowerCase();var nome=document.getElementById('fUserNome').value.trim();var email=document.getElementById('fUserEmail')?document.getElementById('fUserEmail').value.trim().toLowerCase():'';var pass=document.getElementById('fUserPass').value.trim();var isAdminPrincipal=login==='admin';var role=isAdminPrincipal?'Admin':document.getElementById('fUserRole').value;var status=isAdminPrincipal?'ativo':document.getElementById('fUserStatus').value;var locVal=document.getElementById('fUserLocation')?document.getElementById('fUserLocation').value:'';var locationId=locVal?parseInt(locVal,10):null;var areaVal=document.getElementById('fUserArea')?document.getElementById('fUserArea').value:'';var areaId=areaVal?parseInt(areaVal,10):null;var btn=document.getElementById('btnSalvarUser');if(!login||!nome||(!isEdit&&!pass)){toast('Preencha usuário (login), nome e senha.','error');if(!login)document.getElementById('fUserLogin').focus();else if(!nome)document.getElementById('fUserNome').focus();else if(!pass)document.getElementById('fUserPass').focus();return}
var payload={username:login,email:email,name:nome,password:pass,role:role,status:status,location_id:locationId,area_id:areaId};var req=isEdit?api('PUT','/api/users/'+encodeURIComponent(login),payload):api('POST','/api/users',Object.assign({login:login},payload));if(btn){btn.disabled=!0;btn.textContent='Salvando...'}
req.then(function(){fecharModalUsuario();return loadUsers()}).then(function(){toast('Usuário '+(isEdit?'atualizado':'criado')+' com sucesso!')}).catch(function(e){toast(e.message,'error')}).finally(function(){if(btn){btn.disabled=!1;btn.textContent='Salvar'}})}
function confirmDeleteUser(login){deleteTarget={type:'user',id:login};openModal('confirmBG')}
function closeConfirm(){closeModal('confirmBG')}
function confirmDelete(){if(deleteTarget.type==='user'){var btn=document.getElementById('btnConfirmDelete');if(btn){btn.disabled=!0;btn.textContent='Excluindo...'}
api('DELETE','/api/users/'+encodeURIComponent(deleteTarget.id)).then(function(){closeConfirm();return loadUsers()}).then(function(){toast('Usuário excluído.')}).catch(function(e){toast(e.message,'error')}).finally(function(){if(btn){btn.disabled=!1;btn.textContent='Sim, excluir'}})}}
var _autoOpenedUrlParam=!1;function checkUrlEditParam(){if(_autoOpenedUrlParam)return;var params=new URLSearchParams(window.location.search);var editParam=params.get('edit')||params.get('d');if(!editParam)return;_autoOpenedUrlParam=!0;var lowerParam=editParam.toLowerCase().trim();var match=USERS.find(function(u){var login=(u.login||u.username||'').toLowerCase();return login===lowerParam});if(!match){match=USERS.find(function(u){var name=(u.name||'').toLowerCase();var email=(u.email||'').toLowerCase();return name===lowerParam||email===lowerParam})}
if(match){var targetLogin=match.login||match.username;abrirModalUsuario(targetLogin);try{window.history.replaceState({},'','/usuarios')}catch(e){}}else{var input=document.getElementById('userSearchInput');var clearBtn=document.getElementById('userSearchClear');userFilterQuery=editParam;if(input)input.value=editParam;if(clearBtn)clearBtn.hidden=!1;PAGINATION.usr=1;renderAdminUsers();try{window.history.replaceState({},'','/usuarios')}catch(e){}}}
document.addEventListener('DOMContentLoaded',function(){Promise.all([loadRoles().catch(function(){}),loadLocations().catch(function(){}),loadAreas().catch(function(){}),loadUsers().catch(function(e){toast(e.message,'error')})]).then(function(){checkUrlEditParam()});var searchInput=document.getElementById('userSearchInput');var clearBtn=document.getElementById('userSearchClear');if(searchInput){searchInput.addEventListener('input',function(){userFilterQuery=searchInput.value;if(clearBtn)clearBtn.hidden=!userFilterQuery.trim();PAGINATION.usr=1;renderAdminUsers()})}
var userTable=document.getElementById('userTable');if(userTable){TableSort.init(userTable,{onSort:function(){renderAdminUsers()}})}})